.control-block { min-width: 0; }
.name-block { grid-column: 1 / -1; }
.control-block label, .control-heading {
  display: flex; align-items: center; justify-content: space-between;
  margin-bottom: 9px;
  font-size: 0.6rem; font-weight: 600; letter-spacing: 0.2em; text-transform: uppercase;
  color: var(--ink-soft);
}
.control-value { font-size: 0.55rem; font-weight: 400; letter-spacing: 0.08em; text-transform: none; color: var(--muted-2); }
.name-row { display: flex; gap: 8px; }
.name-row input {
  flex: 1; min-width: 0;
  height: 48px;
  padding: 0 16px;
  border-radius: 13px;
  border: 1px solid var(--line-strong);
  background: rgba(255,255,255,0.04);
  color: var(--ink);
  font-family: var(--display);
  font-size: 1.45rem;
  letter-spacing: -0.01em;
  transition: 180ms ease;
}
.name-row input:hover { border-color: rgba(255,255,255,0.32); }
.name-row input:focus { border-color: rgba(255, 195, 170, 0.6); background: rgba(255,255,255,0.06); outline: none; }
.dice-btn {
  width: 48px; height: 48px; flex: none;
  display: grid; place-items: center;
  border-radius: 13px;
  border: 1px solid var(--line-strong);
  background: rgba(255,255,255,0.035);
  color: var(--peach);
  transition: 180ms ease;
}
.dice-btn:hover { transform: rotate(12deg); background: rgba(255,255,255,0.07); }
.dice-btn .icon { width: 17px; height: 17px; fill: currentColor; }
.swatch-row { display: flex; flex-wrap: wrap; gap: 8px; }
.swatch {
  position: relative;
  width: 38px; height: 38px;
  border-radius: 50%;
  border: 1px solid transparent;
  padding: 3px;
  background: transparent;
  transition: 180ms ease;
}
.swatch::before {
  content: ""; display: block; width: 100%; height: 100%; border-radius: 50%;
  background: var(--c);
  box-shadow: inset 0 1px 2px rgba(255,255,255,0.35), inset 0 -2px 5px rgba(0,0,0,0.15);
}
.swatch::after {
  content: ""; position: absolute; inset: -1px;
  border-radius: 50%;
  border: 1px solid transparent;
  transition: 180ms ease;
}
.swatch:hover { transform: translateY(-2px); }
.swatch[aria-pressed="true"]::after { border-color: var(--peach); box-shadow: 0 0 0 3px rgba(255, 195, 170, 0.1); }
.swatch--hair { width: 34px; height: 34px; }
.swatch--eye::before { background: radial-gradient(circle at 48% 45%, #1d101c 0 19%, var(--c) 21% 57%, rgba(255,255,255,0.7) 58% 65%, var(--c) 67%); }

.style-grid { display: grid; grid-template-columns: repeat(4, 1fr); gap: 7px; margin-bottom: 10px; }
.style-tile {
  min-width: 0;
  padding: 9px 4px 8px;
  border-radius: 10px;
  border: 1px solid var(--line);
  background: rgba(255,255,255,0.025);
  color: var(--muted);
  font-size: 0.54rem;
  letter-spacing: 0.045em;
  transition: 180ms ease;
}
.style-tile:hover { color: var(--ink); border-color: var(--line-strong); }
.style-tile[aria-pressed="true"] { color: #2a1420; border-color: transparent; background: linear-gradient(135deg, var(--peach), var(--rose)); font-weight: 700; }
.style-grid--outfit { grid-template-columns: repeat(3, 1fr); }
.style-tile strong { display: block; font-weight: 600; }
.style-tile small { display: block; margin-top: 2px; font-size: 0.48rem; opacity: 0.6; white-space: nowrap; overflow: hidden; text-overflow: ellipsis; }
.personality-row { display: grid; grid-template-columns: 1fr 1fr; gap: 7px; }
.personality {
  text-align: left;
  padding: 10px 11px;
  border-radius: 11px;
  border: 1px solid var(--line);
  background: rgba(255,255,255,0.025);
  color: var(--muted);
  transition: 180ms ease;
}
.personality:hover { border-color: var(--line-strong); }
.personality strong { display: block; color: var(--ink-soft); font-size: 0.67rem; font-weight: 600; }
.personality span { display: block; margin-top: 2px; font-size: 0.53rem; line-height: 1.35; color: var(--muted-2); }
.personality[aria-pressed="true"] { border-color: rgba(255, 195, 170, 0.5); background: rgba(255, 182, 167, 0.09); }
.personality[aria-pressed="true"] strong { color: var(--peach); }
.creator-footer { grid-column: 1 / -1; display: flex; align-items: center; justify-content: space-between; gap: 16px; padding-top: 4px; }
.creator-footer .btn { flex: none; }
.creator-footer .fineprint { max-width: 190px; font-size: 0.62rem; }

/* ---------- game ---------- */
.game-screen { padding-top: 4px; }
.game-grid {
  display: grid;
  grid-template-columns: minmax(0, 1.06fr) minmax(420px, 0.94fr);
  gap: 18px;
  height: calc(100dvh - 88px - var(--safe-top) - var(--safe-bottom));
  min-height: 560px;
  max-height: 880px;
  max-width: 1360px;
  margin: 0 auto;
}
.scene-panel {
  position: relative;
  border-radius: 28px;
  overflow: hidden;
  border: 1px solid rgba(255, 228, 238, 0.15);
  background: var(--scene-bg, linear-gradient(180deg, #241a39 0%, #151022 70%));
  box-shadow: var(--shadow), inset 0 1px 0 rgba(255,255,255,0.07);
  isolation: isolate;
}
.scene-wash {
  position: absolute; inset: 0;
  background:
    radial-gradient(circle at 50% 27%, var(--scene-glow, rgba(255,165,167,0.3)), transparent 45%),
    linear-gradient(180deg, transparent 45%, rgba(7,5,13,0.58));
  transition: background 900ms ease;
}
.scene-stars { position: absolute; inset: 0; opacity: 0.8; }
.scene-moon {
  position: absolute;
  width: min(31%, 190px); aspect-ratio: 1;
  left: 8%; top: 9%;
  border-radius: 50%;
  background: radial-gradient(circle at 36% 34%, #fff5dc, #ffd9c1 44%, #e6a7a2 78%);
  box-shadow: 0 0 80px 8px rgba(255, 197, 177, 0.25);
  opacity: 0.85;
  transition: 900ms ease;
}
.scene-moon::after {
  content: ""; position: absolute; inset: 0; border-radius: 50%;
  background: radial-gradient(circle at 63% 32%, rgba(155, 96, 116, 0.2) 0 6%, transparent 8%),
              radial-gradient(circle at 45% 61%, rgba(155, 96, 116, 0.16) 0 10%, transparent 12%);
}
.scene-skyline {
  position: absolute; left: -3%; right: -3%; bottom: 0; height: 34%;
  background: linear-gradient(180deg, #100b19 0%, #0b0712 100%);
  clip-path: polygon(0 44%, 4% 44%, 4% 29%, 7% 29%, 7% 52%, 12% 52%, 12% 19%, 15% 19%, 15% 39%, 20% 39%, 20% 61%, 24% 61%, 24% 35%, 28% 35%, 28% 48%, 33% 48%, 33% 15%, 37% 15%, 37% 54%, 42% 54%, 42% 39%, 46% 39%, 46% 58%, 51% 58%, 51% 25%, 55% 25%, 55% 47%, 59% 47%, 59% 17%, 63% 17%, 63% 38%, 68% 38%, 68% 54%, 72% 54%, 72% 31%, 76% 31%, 76% 49%, 81% 49%, 81% 21%, 85% 21%, 85% 43%, 90% 43%, 90% 33%, 94% 33%, 94% 53%, 100% 53%, 100% 100%, 0 100%);
  filter: drop-shadow(0 -5px 18px rgba(255, 156, 178, 0.06));
}
.scene-skyline::after {
  content: ""; position: absolute; inset: 0;
  background-image:
    radial-gradient(circle, rgba(255, 202, 158, 0.7) 0 1px, transparent 1.6px),
    radial-gradient(circle, rgba(255, 160, 184, 0.5) 0 1px, transparent 1.6px);
  background-size: 41px 34px, 57px 47px;
  background-position: 6px 12px, 28px 29px;
  -webkit-mask-image: linear-gradient(180deg, transparent 5%, #000 30%);
  mask-image: linear-gradient(180deg, transparent 5%, #000 30%);
  opacity: 0.55;
}
.scene-portrait { position: absolute; inset: 2% -3% 0; z-index: 2; display: grid; place-items: end center; }
.scene-portrait svg {
  width: 100%; height: 100%;
  max-width: 590px;
  filter: drop-shadow(0 30px 52px rgba(0,0,0,0.52));
  animation: portraitIn 1.2s cubic-bezier(.2,.75,.25,1) both;
}
@keyframes portraitIn { from { opacity: 0; transform: translateY(18px) scale(0.975); } to { opacity: 1; transform: none; } }
.scene-vignette {
  position: absolute; inset: 0; z-index: 3; pointer-events: none;
  background:
    linear-gradient(180deg, rgba(7,5,13,0.35) 0%, transparent 22%, transparent 63%, rgba(8,5,13,0.55) 100%),
    radial-gradient(ellipse at center, transparent 50%, rgba(7,5,13,0.34) 100%);
}
.scene-top {
  position: absolute; top: 20px; left: 20px; right: 20px; z-index: 5;
  display: flex; align-items: center; justify-content: space-between; gap: 10px;
}
.scene-tags { display: flex; align-items: center; gap: 9px; min-width: 0; }
.scene-place {
  padding: 7px 11px;
  border: 1px solid rgba(255,255,255,0.14);
  border-radius: 999px;
  background: rgba(15, 10, 22, 0.32);
  backdrop-filter: blur(10px);
  -webkit-backdrop-filter: blur(10px);
  font-size: 0.55rem; letter-spacing: 0.11em; text-transform: uppercase; color: var(--ink-soft);
  white-space: nowrap; overflow: hidden; text-overflow: ellipsis;
}
.scene-time { font-size: 0.55rem; letter-spacing: 0.15em; color: rgba(255,255,255,0.48); }
.glass-btn {
  display: flex; align-items: center; gap: 7px;
  padding: 7px 11px;
  border-radius: 999px;
  border: 1px solid rgba(255,255,255,0.14);
  background: rgba(15, 10, 22, 0.32);
  backdrop-filter: blur(10px);
  -webkit-backdrop-filter: blur(10px);
  color: var(--muted);
  font-size: 0.53rem; letter-spacing: 0.14em; text-transform: uppercase;
}
.glass-btn:hover { color: var(--ink); border-color: var(--line-strong); }
.glass-dot { width: 5px; height: 5px; border-radius: 50%; background: var(--peach); box-shadow: 0 0 8px var(--peach); }
.affection-widget {
  position: absolute; z-index: 5; left: 20px; bottom: 55px;
  width: min(220px, 59%);
  padding: 11px 13px 10px;
  border: 1px solid rgba(255,255,255,0.14);
  border-radius: 13px;
  background: rgba(15, 10, 22, 0.35);
  backdrop-filter: blur(14px);
  -webkit-backdrop-filter: blur(14px);
}
.affection-top { display: flex; align-items: center; justify-content: space-between; margin-bottom: 7px; }
.affection-top span { display: flex; align-items: center; gap: 5px; font-size: 0.51rem; text-transform: uppercase; letter-spacing: 0.15em; color: var(--ink-soft); }
.affection-top .icon { width: 11px; height: 11px; color: var(--rose); fill: currentColor; }
.affection-top strong { font-family: var(--display); font-size: 0.92rem; font-weight: 600; color: var(--peach); }
.affection-track { height: 3px; border-radius: 10px; background: rgba(255,255,255,0.13); overflow: hidden; }
.affection-track span {
  display: block; height: 100%; width: 0;
  border-radius: inherit;
  background: linear-gradient(90deg, var(--lilac), var(--rose), var(--peach));
  box-shadow: 0 0 8px rgba(255, 157, 173, 0.7);
  transition: width 800ms cubic-bezier(.2,.75,.25,1);
}
.affection-label { margin-top: 6px; font-size: 0.49rem; color: var(--muted-2); letter-spacing: 0.06em; }
.scene-foot {
  position: absolute; z-index: 5; left: 20px; right: 20px; bottom: 17px;
  display: flex; align-items: center; gap: 8px;
  font-size: 0.48rem; letter-spacing: 0.16em; text-transform: uppercase; color: rgba(255,255,255,0.34);
}
.scene-foot-line { height: 1px; flex: 1; background: rgba(255,255,255,0.11); }

/* scene color moods */
.scene-panel[data-scene="rooftop"] { --scene-bg: linear-gradient(180deg, #22162f 0%, #30203c 45%, #120c1c 100%); --scene-glow: rgba(255, 174, 163, 0.3); }
.scene-panel[data-scene="bookshop"] { --scene-bg: linear-gradient(180deg, #291d2b 0%, #3c2b34 48%, #130d16 100%); --scene-glow: rgba(246, 189, 141, 0.24); }
.scene-panel[data-scene="bookshop"] .scene-moon { opacity: 0.2; }
.scene-panel[data-scene="bookshop"]::after {
  content: ""; position: absolute; inset: 0; z-index: 1; pointer-events: none;
  background: repeating-linear-gradient(100deg, transparent 0 50px, rgba(255,195,159,0.028) 51px 52px, transparent 53px 128px);
}
.scene-panel[data-scene="kitchen"] { --scene-bg: linear-gradient(180deg, #1e1c2c 0%, #32303a 46%, #111018 100%); --scene-glow: rgba(255, 210, 164, 0.25); }
.scene-panel[data-scene="kitchen"] .scene-moon { left: auto; right: 6%; top: 15%; width: 90px; opacity: 0.55; }
.scene-panel[data-scene="arcade"] { --scene-bg: linear-gradient(180deg, #15172d 0%, #251439 46%, #0d0815 100%); --scene-glow: rgba(141, 183, 255, 0.23); }
.scene-panel[data-scene="arcade"] .scene-moon { width: 210px; background: radial-gradient(circle at 35% 35%, #f7b9ff, #b47ff1 50%, #7a51d6 80%); opacity: 0.4; }
.scene-panel[data-scene="arcade"] .scene-wash {
  background: radial-gradient(circle at 25% 30%, rgba(107, 161, 255, 0.21), transparent 40%), radial-gradient(circle at 76% 22%, rgba(255, 112, 170, 0.22), transparent 36%), linear-gradient(180deg, transparent 46%, rgba(7,5,13,0.66));
}
.scene-panel[data-scene="observatory"] { --scene-bg: linear-gradient(180deg, #10162c 0%, #24213a 48%, #0c0a15 100%); --scene-glow: rgba(165, 178, 255, 0.22); }
.scene-panel[data-scene="observatory"] .scene-moon { width: 95px; left: 70%; top: 12%; opacity: 0.72; }
.scene-panel[data-scene="dawn"] { --scene-bg: linear-gradient(180deg, #5a3f58 0%, #c17b77 48%, #2a1928 100%); --scene-glow: rgba(255, 205, 164, 0.45); }
.scene-panel[data-scene="dawn"] .scene-skyline { opacity: 0.8; }
.scene-panel[data-scene="dawn"] .scene-moon { background: radial-gradient(circle at 40% 38%, #fff8e3, #ffcfae 60%, #ec9e90 100%); opacity: 0.6; }

.dialogue-panel {
  position: relative;
  display: flex; flex-direction: column;
  min-height: 0;
  padding: clamp(22px, 2.6vw, 34px);
  border-radius: 28px;
  border: 1px solid rgba(255, 230, 239, 0.13);
  background:
    linear-gradient(180deg, rgba(33, 23, 47, 0.82), rgba(15, 10, 24, 0.91));
  backdrop-filter: blur(22px);
  -webkit-backdrop-filter: blur(22px);
  box-shadow: var(--shadow), inset 0 1px 0 rgba(255,255,255,0.055);
  overflow: hidden;
}
.dialogue-panel::before {
  content: ""; position: absolute; inset: 0 0 auto; height: 150px; pointer-events: none;
  background: radial-gradient(ellipse at 60% 0%, rgba(255, 173, 172, 0.11), transparent 65%);
}
.chapter-row { position: relative; display: flex; align-items: flex-start; justify-content: space-between; gap: 20px; padding-bottom: 16px; border-bottom: 1px solid var(--line); }
.chapter-kicker { margin-bottom: 7px; font-size: 0.55rem; color: var(--rose); }
.chapter-title {
  margin: 0;
  font-family: var(--display);
  font-weight: 500;
  font-size: clamp(1.65rem, 2.3vw, 2.35rem);
  line-height: 1; letter-spacing: -0.025em;
}
.text-btn {
  padding: 5px 0;
  border: 0; background: none;
  color: var(--muted-2);
  font-size: 0.52rem; letter-spacing: 0.16em; text-transform: uppercase;
  transition: color 180ms ease;
}
.text-btn:hover { color: var(--ink); }
.dialogue-scroll {
  display: flex; flex-direction: column;
  flex: 1; min-height: 0;
  overflow-y: auto;
  padding: clamp(20px, 3vh, 34px) 2px 12px;
  scrollbar-width: thin;
  scrollbar-color: rgba(255,255,255,0.15) transparent;
}
.speaker-row { display: flex; align-items: center; gap: 8px; margin-bottom: 14px; }
.speaker-avatar {
  display: grid; place-items: center;
  width: 25px; height: 25px;
  border-radius: 50%;
  background: linear-gradient(135deg, rgba(255,195,170,0.25), rgba(255,150,173,0.16));
  border: 1px solid rgba(255,200,180,0.26);
  color: var(--peach);
  font-family: var(--display); font-size: 0.8rem; font-weight: 600;
}
.speaker-name { font-size: 0.63rem; font-weight: 700; letter-spacing: 0.15em; text-transform: uppercase; color: var(--peach); }
.speaker-tag { font-size: 0.54rem; letter-spacing: 0.05em; color: var(--muted-2); }
.speaker-row.narrator .speaker-avatar { background: rgba(255,255,255,0.06); border-color: var(--line); color: var(--muted); }
.speaker-row.narrator .speaker-name { color: var(--muted); }
.speaker-row.narrator .speaker-tag { display: none; }
.dialogue-text {
  margin: 0;
  font-family: var(--display);
  font-size: clamp(1.42rem, 2.05vw, 1.9rem);
  font-weight: 400;
  line-height: 1.35;
  letter-spacing: -0.012em;
  color: var(--ink);
  text-wrap: pretty;
}
.dialogue-text .accent { color: var(--peach); font-style: italic; }
.dialogue-text .cursor {
  display: inline-block; width: 1px; height: 0.9em; margin-left: 2px;
  background: var(--peach); vertical-align: -0.05em;
  animation: cursorBlink 0.8s steps(1) infinite;
}
@keyframes cursorBlink { 50% { opacity: 0; } }
.narrator-text {
  margin: 16px 0 0;
  padding-left: 14px;
  border-left: 1px solid rgba(255,195,170,0.32);
  color: var(--muted);
  font-size: 0.74rem;
  line-height: 1.7;
}
.choices-wrap { position: relative; padding-top: 4px; }
.choice-heading {
  display: flex; align-items: center; gap: 12px;
  margin-bottom: 8px;
  font-size: 0.51rem; font-weight: 600; letter-spacing: 0.18em; text-transform: uppercase; color: var(--muted-2);
}
.choice-rule { flex: 1; height: 1px; background: var(--line); }
.choices { display: flex; flex-direction: column; gap: 7px; }
.choice {
  position: relative;
  display: flex; align-items: center; gap: 12px;
  width: 100%;
  min-height: 46px;
  padding: 11px 14px 11px 12px;
  text-align: left;
  border-radius: 12px;
  border: 1px solid rgba(255, 230, 239, 0.1);
  background: rgba(255, 255, 255, 0.028);
  color: var(--ink-soft);
  font-size: 0.76rem;
  line-height: 1.35;
  transition: transform 180ms ease, border-color 180ms ease, background 180ms ease;
  animation: choiceIn 420ms cubic-bezier(.2,.75,.25,1) both;
}
.choice:nth-child(2) { animation-delay: 70ms; }
.choice:nth-child(3) { animation-delay: 140ms; }
@keyframes choiceIn { from { opacity: 0; transform: translateY(8px); } to { opacity: 1; transform: none; } }
.choice:hover { transform: translateX(3px); border-color: rgba(255, 195, 170, 0.4); background: rgba(255, 185, 175, 0.075); }
.choice:active { transform: scale(0.992); }
.choice-key {
  display: grid; place-items: center;
  width: 23px; height: 23px; flex: none;
  border-radius: 50%;
  border: 1px solid rgba(255,255,255,0.14);
  color: var(--muted-2);
  font-family: var(--display); font-size: 0.72rem;
  transition: 180ms ease;
}
.choice:hover .choice-key { border-color: var(--peach); color: var(--peach); }
.choice-text { flex: 1; }
.choice-spark { opacity: 0; color: var(--peach); transition: opacity 180ms ease; }
.choice:hover .choice-spark { opacity: 0.8; }
.choice-spark .icon { width: 12px; height: 12px; fill: currentColor; }
.choice.selected { border-color: rgba(255, 195, 170, 0.5); background: rgba(255, 179, 167, 0.09); }
.continue-wrap { padding-top: 8px; animation: choiceIn 350ms ease both; }
.save-state { display: inline-flex; align-items: center; gap: 6px; font-size: 0.48rem; letter-spacing: 0.12em; text-transform: uppercase; color: var(--muted-2); }
.save-dot { width: 4px; height: 4px; border-radius: 50%; background: var(--mint); box-shadow: 0 0 7px rgba(183,240,220,0.6); }
.dialogue-foot { display: flex; align-items: center; justify-content: space-between; padding-top: 14px; border-top: 1px solid var(--line); }
.progress-dots { display: flex; gap: 5px; }
.progress-dot { width: 5px; height: 5px; border-radius: 999px; background: rgba(255,255,255,0.14); transition: 300ms ease; }
.progress-dot.is-done { background: rgba(255,195,170,0.5); }
.progress-dot.is-current { width: 18px; background: var(--peach); box-shadow: 0 0 8px rgba(255,195,170,0.5); }
.choice-result { display: flex; align-items: center; gap: 8px; padding: 13px 0 2px; font-size: 0.57rem; letter-spacing: 0.12em; text-transform: uppercase; color: var(--peach); animation: choiceIn 350ms ease both; }
.choice-result .icon { width: 12px; height: 12px; fill: currentColor; }
.choice-result .delta { font-family: var(--display); font-size: 0.95rem; letter-spacing: 0; }
.choice-result .result-note { margin-left: auto; color: var(--muted-2); letter-spacing: 0.04em; text-transform: none; }

/* ---------- ending ---------- */
.ending-screen { min-height: calc(100dvh - 74px); display: none; padding-top: 10px; padding-bottom: 40px; }
.ending-screen.is-active { display: flex; align-items: center; justify-content: center; }
.ending-grid {
  width: min(1180px, 100%);
  display: grid;
  grid-template-columns: minmax(300px, 0.9fr) minmax(0, 1.1fr);
  align-items: center;
  gap: clamp(28px, 5vw, 75px);
}
.ending-art {
  position: relative;
  aspect-ratio: 0.84;
  max-height: 76vh;
  border-radius: 240px 240px 28px 28px;
  border: 1px solid rgba(255, 228, 236, 0.16);
  background:
    radial-gradient(circle at 50% 28%, rgba(255, 193, 160, 0.28), transparent 48%),
    linear-gradient(170deg, rgba(91, 58, 84, 0.55), rgba(18, 12, 26, 0.78));
  box-shadow: var(--shadow), inset 0 1px 0 rgba(255,255,255,0.08);
  overflow: hidden;
}
.ending-art::before {
  content: ""; position: absolute; inset: 8%;
  border: 1px solid rgba(255, 227, 234, 0.14);
  border-radius: 200px 200px 20px 20px;
}
.ending-art svg { position: absolute; inset: 5% 0 0; width: 100%; height: 100%; filter: drop-shadow(0 30px 50px rgba(0,0,0,0.42)); }
.ending-copy .eyebrow { margin-bottom: 16px; }
.ending-copy h2 {
  margin: 0 0 22px;
  font-family: var(--display); font-weight: 500;
  font-size: clamp(3.6rem, 7vw, 6.8rem);
  line-height: 0.82; letter-spacing: -0.055em;
}
.ending-copy h2 em { color: var(--peach); font-weight: 500; }
