/* ---------- portrait svg animations ---------- */
.portrait-svg .blink-group { transform-box: fill-box; transform-origin: center; animation: blink 7s infinite; }
.portrait-svg .blink-group.delay { animation-delay: 0.12s; }
@keyframes blink {
