.portrait-svg .sparkle { animation: sparkle 5s ease-in-out infinite; transform-box: fill-box; transform-origin: center; }
.portrait-svg .sparkle:nth-of-type(2) { animation-delay: -1.8s; }
.portrait-svg .sparkle:nth-of-type(3) { animation-delay: -3.1s; }
@keyframes sparkle { 0%,100% { opacity: 0.2; transform: scale(0.7); } 50% { opacity: 0.9; transform: scale(1.1); } }

