function safeName(value) {
  const clean = String(value || '').replace(/[<>"'&]/g, '').trim().slice(0, 16);
  return clean || 'Lia';
}
function escapeHTML(value) {
  return String(value).replace(/[&<>"']/g, (char) => ({ '&': '&amp;', '<': '&lt;', '>': '&gt;', '"': '&quot;', "'": '&#39;' })[char]);
}
function save() {
  try { localStorage.setItem('halcyon-save', JSON.stringify(state)); } catch (error) { console.warn('Save unavailable', error); }
  const text = $('#saveStateText');
  if (text) text.textContent = 'autosaved';
  $('#continueBtn').hidden = !(state.screen === 'game' || state.screen === 'ending' || state.screen === 'creator');
}
function load() {
  try {
    const parsed = JSON.parse(localStorage.getItem('halcyon-save') || 'null');
    if (!parsed) return;
    state = { ...defaults, ...parsed, name: safeName(parsed.name), memories: Array.isArray(parsed.memories) ? parsed.memories.slice(0, 5) : [], choices: Array.isArray(parsed.choices) ? parsed.choices.slice(0, 5) : [] };
    for (const key of ['skin', 'hair', 'hairColor', 'eyes', 'outfit', 'personality']) state[key] = Math.max(0, Number(state[key]) || 0);
    state.skin %= palettes.skin.length; state.hair %= palettes.hairStyles.length; state.hairColor %= palettes.hair.length;
    state.eyes %= palettes.eyes.length; state.outfit %= palettes.outfits.length; state.personality %= palettes.personalities.length;
    state.night = Math.min(5, Math.max(0, Number(state.night) || 0));
    if (!['title', 'creator', 'game', 'ending'].includes(state.screen)) state.screen = 'title';
  } catch { state = { ...defaults }; }
}
function setScreen(screen) {
  state.screen = screen;
  $$('.screen').forEach((el) => el.classList.toggle('is-active', el.id === `${screen}Screen`));
  $('#topMetaText').textContent = screen === 'game' ? 'five nights between heartbeats' : 'a dream girl story';
  document.body.dataset.screen = screen;
  if (screen === 'game') renderStory();
  save();
  window.scrollTo({ top: 0, behavior: 'smooth' });
}

